ITEMS += [
dict(id='2.9.1',sub='Economy',nb=['eco'],ch=['eco-ch07','eco-ch08'],tag='P',
 t='MDR on high-value UPI merchant payments',
 ctx='NPCI announced a Merchant Discount Rate on select high-value person-to-merchant (P2M) UPI payments under the Payment and Settlement Systems Act, 2007. UPI stays free for P2P.',
 pts=['MDR: fee a merchant pays its bank for accepting digital payments, as a percentage of value; shared among acquiring bank, issuing bank, UPI app and NPCI.',
 'Framework: P2P free (any amount); P2M up to Rs 2,000 free; above Rs 2,000 0.4%; capped at Rs 300 for Rs 75,000 and above; essential sectors (railways, telecom, insurance, fuel, utilities) above Rs 2,000 flat Rs 5.',
 'A Small Merchant Fund from part of MDR revenue for Tier 3-6 centres, North-East, J&K, Ladakh, and PM SVANidhi and PM Vishwakarma beneficiaries. Merchants cannot pass MDR to customers.'],
 kw='MDR; P2M; PSS Act 2007; UPI sustainability'),
dict(id='2.9.2',sub='Economy',nb=['eco'],ch=['eco-ch12','eco-ch09'],tag='P',
 t='National Investment and Infrastructure Fund (NIIF)',
 ctx='NIIF Infrastructure Fund II has raised about Rs 19,000 crore towards a Rs 30,000 crore target. Fund I had about Rs 16,000 crore.',
 pts=['NIIF is a sovereign-anchored fund (government a key investor, also draws large domestic and global institutions), run by NIIFL; Government holds 49%.','Funds: Master fund, fund of funds (e.g. India-UK Green Growth Equity Fund), Strategic Opportunities Fund, India-Japan Fund.'],
 kw='Sovereign-anchored fund',
 pyq='2017 Prelims: NIIF is not an organ of NITI Aayog and does not have a corpus of Rs 4,00,000 crore.'),
dict(id='2.9.3',sub='Economy',nb=['eco'],ch=['eco-ch05'],tag='P',
 t='Double deflation in GDP estimation',
 ctx='Q1 FY27 real GDP grew 7.8% and nominal GDP 10.3%, an implicit GDP deflator of about 2.3%.',
 pts=['GDP deflator: change in prices of all domestically produced goods and services, from nominal and real GDP.','The new 2022-23 base series makes wider use of double deflation: real GVA estimated by deflating output and intermediate inputs separately (GVA = output minus intermediate inputs), more accurate when their prices move differently, especially in manufacturing.'],
 kw='Double deflation; GDP deflator; GVA; base year 2022-23'),
dict(id='2.9.4',sub='Economy',nb=['eco','gs3'],ch=['gs3-ch35'],tag='P',
 t='Mega Ports notified under the Indian Ports Act, 2025',
 ctx='Deendayal (Kandla), Jawaharlal Nehru (Nhava Sheva), Paradip and Mundra were notified as mega ports under Section 73 of the Indian Ports Act, 2025.',
 pts=['Eligibility: major and non-major ports (State consulted for non-major). Cargo threshold: at least 150 MMT in the previous year or 7.5 million TEUs. Validity: five years.','Deendayal: Gulf of Kutch, largest major port by cargo (2025-26), tidal port. Mundra: Gulf of Kutch, private (Adani Ports), non-major. JNPT: Navi Mumbai, most containerised trade. Paradip: Odisha (Mahanadi delta), only mega port on the east coast.','India: 14 major ports (12 operating) and over 200 non-major ports. Major ports: Union List, Major Port Authorities Act, 2021. Non-major: Concurrent List, State Maritime Boards. Ports carry about 95% of trade by volume and 70% by value.'],
 kw='Mega port; Indian Ports Act 2025; TEU'),
dict(id='2.9.5',sub='Economy',nb=['eco'],ch=['eco-ch10'],tag='PM',
 t='Districts as Export Hubs (DEH)',
 ctx='The Districts as Export Hubs initiative now covers over 770 districts. India\'s goods and services exports were US$ 825.25 billion in 2024-25.',
 pts=['Aim: turn every district into an export hub by finding export-potential products and services, removing bottlenecks, improving market access. Nodal: Department of Commerce; implemented by DGFT; institutionalised under FTP 2023. A convergence framework using existing Central and State schemes.','ODOP vs DEH: ODOP focuses on a distinctive product (branding, promotion); DEH on the whole district export ecosystem (products, services, logistics, standards, market access) through Centre-State-District convergence.','Focused implementation phase from June 2026 in 27 States/UTs with 24 DGFT regional authorities; focus on exporter activation, capacity building and export growth.'],
 kw='Export ecosystem; Centre-State-District convergence; ODOP'),
dict(id='2.10.1',sub='Economy',nb=['eco'],ch=['eco-ch08'],tag='P',
 t='Variable Rate Reverse Repo (VRRR)',
 ctx='RBI absorbed over Rs 6.02 lakh crore in two three-day VRRR auctions; both cut-off rates were 5.24%.',
 pts=['VRRR: RBI absorbs surplus funds from banks for a set period at a rate found by competitive bidding. Keeps short-term rates aligned with the policy stance.','VRRR absorbs liquidity; Variable Rate Repo (VRR) injects liquidity.'],
 kw='Liquidity absorption; Competitive bidding'),
dict(id='2.10.2',sub='Economy',nb=['eco'],ch=['eco-ch09'],tag='P',
 t='Certificate of Deposit (CD)',
 ctx='Three-month CD rates fell to about 6.3% from 7.09-7.23% in June 2026, as FCNR(B) inflows (about $127.2 billion) raised liquidity and cut banks\' need for wholesale funds.',
 pts=['CD: negotiable money market instrument against funds deposited for a fixed period; issued by scheduled commercial banks (not RRBs, Local Area Banks) and eligible AIFIs; bank CDs mature in 7 days to one year.'],
 kw='Money market instrument',
 pyq='2020 Prelims: CD is not a long-term RBI instrument; commercial paper is a short-term unsecured note; call money is for inter-bank use.'),
dict(id='2.10.3',sub='Economy',nb=['gs3','eco'],ch=['gs3-ch51'],tag='P',
 t='Financial Fraud Risk Indicator (FRI)',
 ctx='DoT said FRI helped prevent suspected cyber-fraud transactions worth over Rs 5,000 crore within 15 months of launch.',
 pts=['Introduced 2025 by DoT\'s Digital Intelligence Unit, on the Digital Intelligence Platform. Classes mobile numbers as Medium, High or Very High fraud risk, using I4C\'s NCRP, Chakshu, and bank data. Banks, NBFCs and UPI providers use it in real time; RBI advised integration.'],
 kw='FRI; I4C; NCRP; Chakshu'),
dict(id='2.10.4',sub='Economy',nb=['eco'],ch=['eco-ch09'],tag='P',
 t='Demutualisation of stock exchanges (NSE IPO)',
 ctx='NSE launched its IPO, bringing demutualisation into focus.',
 pts=['Demutualisation converts a member-owned exchange into a shareholder-owned company, separating ownership from trading rights, to reduce broker conflict of interest. SEBI\'s group under Justice M.H. Kania (2002) recommended corporatisation and demutualisation.'],
 kw='Demutualisation; Kania group'),
dict(id='2.10.5',sub='Economy',nb=['eco'],ch=['eco-ch09'],tag='P',
 t='Demat 2.0 (tokenised corporate bonds)',
 ctx='SEBI and RBI launched the Demat 2.0 pilot for tokenised corporate bonds using Distributed Ledger Technology and wholesale digital rupee settlement.',
 pts=['Bonds are DLT tokens rather than book-entry records; settlement uses wholesale CBDC (e-rupee) through the Unified Market Interface with atomic settlement; smart contracts automate interest and redemption.','India is the first country to issue bonds natively on a statutory depository-owned distributed ledger with CBDC settlement. Pilot: REC, L&T and IIFL issued tokenised bonds worth Rs 1,025 crore.'],
 kw='DLT; Wholesale CBDC; Atomic settlement; Smart contract'),
dict(id='2.10.6',sub='Economy',nb=['eco'],ch=['eco-ch09'],tag='P',
 t='SEBI\'s IT Resilience Index (ITRI)',
 ctx='SEBI introduced ITRI for Market Infrastructure Institutions (exchanges, clearing corporations, depositories).',
 pts=['System-driven index of 9 parameters totalling 100; Availability (20%) and Security (20%) weigh most. Others: Integrity, Governance, Reliability and Monitoring, Business Continuity, Modularity and Flexibility, Scalability, Incident Handling.'],
 kw='ITRI; MII'),
dict(id='2.10.7',sub='Economy',nb=['eco'],ch=['eco-ch07'],tag='P',
 t='National Company Law Tribunal (NCLT)',
 ctx='A special five-member NCLT Bench stayed approval of Subhash Chandra\'s repayment plan in his personal insolvency case and restrained transfer of his assets.',
 pts=['NCLT: constituted under Section 408, Companies Act, 2013; operational 2016; quasi-judicial. Principal Bench in New Delhi; sanctioned strength 62 (31 Judicial and 31 Technical). President must be or have been a High Court judge for five years. Handles Companies Act and IBC 2016 matters; appeal lies to NCLAT.'],
 kw='NCLT; NCLAT; IBC'),
dict(id='2.10.8',sub='Economy',nb=['eco'],ch=['eco-ch12'],tag='P',
 t='Corporate Mitra Scheme',
 ctx='First batch of the Corporate Mitra Course began with 2,879 learners, after the Union Budget 2026-27 announcement.',
 pts=['Builds accredited para-professionals for ease of doing business. Academic support: ICAI, ICSI, ICoAI. Areas: accounting, taxation, banking, financial management, legal and secretarial practice, cost accounting. Eligibility: Indian nationals up to 30 years, graduates or final-year students; certified after assessment and on-the-job training.'],
 kw='Para-professionals; Ease of doing business'),
dict(id='2.10.9',sub='Economy',nb=['eco'],ch=['eco-ch10'],tag='P',
 t='Copper price rise',
 ctx='Copper prices are up on short-term supply disruption and structural demand growth.',
 pts=['Causes: ageing mines and disruptions; demand from EVs and AI/data centres; US tariff expectations drawing stocks to the US.','Copper: non-ferrous base metal with high electrical and thermal conductivity; about three-fourths of use is electrical. Top producers: Chile, Peru, DR Congo. India: Madhya Pradesh, Rajasthan, Jharkhand.'],
 kw='Critical minerals; Base metal'),
dict(id='2.10.10',sub='Economy',nb=['eco'],ch=['eco-ch10'],tag='P',
 t='Anti-dumping duties on aluminium products',
 ctx='DGTR recommended extending anti-dumping duty for five years on certain aluminium imports.',
 pts=['Dumping: selling abroad below the home-market price. Governed by the WTO Anti-Dumping Agreement (Article VI of GATT 1994).','DGTR: attached office of the Department of Commerce; investigates anti-dumping, countervailing and safeguard cases.'],
 kw='DGTR; Trade remedies'),
dict(id='2.10.11',sub='Economy',nb=['eco'],ch=['eco-ch12'],tag='P',
 t='BIS: compulsory certification for screen protectors',
 ctx='BIS certification is compulsory for smartphone screen protectors from 1 April 2027.',
 pts=['Screen protectors are the 66th product under the Electronics and IT Goods (Requirement of Compulsory Registration) Order, 2021; standard IS 19348:2025; notified under the BIS Act, 2016.','BIS: national standards body (BIS Act, 2016): standards, certification, compulsory registration, hallmarking, labs; HQ New Delhi.'],
 kw='BIS Act 2016; Compulsory registration'),
dict(id='2.10.12',sub='Economy',nb=['eco'],ch=['eco-ch12'],tag='P',
 t='First global road surface dataset',
 ctx='Heidelberg University and HeiGIT built the first global multi-temporal dataset of road surface conditions.',
 pts=['Maps 95.5% of 9.2 million km of critical arterial roads for 2020 and 2024 (nearly half previously unclassified), using deep learning and 3-4 metre PlanetScope imagery to detect pavedness and width. Useful for infrastructure planning, climate adaptation and humanitarian logistics.'],
 kw='Geospatial AI'),
dict(id='2.10.13',sub='Economy',nb=['eco'],ch=['eco-ch12'],tag='P',
 t='India\'s first LNG-powered train',
 ctx='Flagged off from Sabarmati, Gujarat.',
 pts=['Eight-coach non-AC modified DEMU by ICF Chennai; two 1,400 hp power cars run on LNG and diesel; LNG can replace about 40% of diesel.','LNG: natural gas cooled to about -161 deg C, 95-99% methane; calorific value 47-50 MJ/kg (diesel about 45.6). India imported about 34.2 BCM in FY26, with import dependence of about 49%.'],
 kw='LNG; DEMU; Dual fuel'),
dict(id='2.10.14',sub='Economy',nb=['eco','gs3'],ch=['gs3-ch11'],tag='P',
 t='KAVACH',
 ctx='Railways approved Rs 223 crore for Kavach 4.0 on 614.75 route km of Varanasi Division, North Eastern Railway.',
 pts=['Indigenous Automatic Train Protection system developed through RDSO; National ATP system since 2020; SIL-4 certified. Prevents Signal Passing at Danger (SPAD), overspeeding and collisions by automatic braking. Kavach 4.0 (approved 2024): better location accuracy, signal information, station-to-station optical fibre, electronic interlocking integration. Uses RFID tags, trackside systems and radio.'],
 kw='ATP; SIL-4; RDSO'),
dict(id='2.10.15',sub='Economy',nb=['gs3'],ch=['gs3-ch02','gs3-ch01'],tag='P',
 t='CAZRI moth bean varieties',
 ctx='Four ICAR-CAZRI varieties (Moth-4, 5, 6, 7) held up through a 35-day dry spell in Kharif 2026 in western Rajasthan.',
 pts=['Moth bean (Vigna aconitifolia): drought-hardy kharif pulse; 25-37 deg C and 250-500 mm rain; also fodder and green manure; Rajasthan gives about 96% of output.','CAZRI: ICAR institute at Jodhpur; began as the Desert Afforestation Research Station (1952); CAZRI since 1959.'],
 kw='Drought resilience; Arid farming'),
dict(id='2.10.16',sub='Economy',nb=['gs3'],ch=['gs3-ch03','gs3-ch01'],tag='P',
 t='Red rot disease in sugarcane',
 ctx='Uttar Pradesh sugar output fell from 126.4 lakh tonnes (2019-20) to 89.5 lakh tonnes (2025-26), mainly from red rot spread.',
 pts=['Variety Co-0238 (Karan 4) has become susceptible. Red rot: fungal disease caused by Colletotrichum falcatum, the "cancer of sugarcane"; reddish internal tissue, wilting, rotting stalks; spreads via infected setts, residues and waterlogging.'],
 kw='Colletotrichum falcatum; Varietal replacement'),
dict(id='2.10.17',sub='Economy',nb=['gs3'],ch=['gs3-ch05','gs3-ch06'],tag='P',
 t='Pashudhan Bima Portal',
 ctx='Launched by the Ministry of Fisheries, Animal Husbandry and Dairying.',
 pts=['Single digital platform for livestock insurance under the Livestock Insurance Scheme (a component of the National Livestock Mission); online applications, policy issue, claims, monitoring.'],
 kw='Livestock insurance'),
dict(id='2.10.18',sub='Economy',nb=['gs3'],ch=['gs3-ch05'],tag='PM',
 t='PMMSY completes six years',
 ctx='Pradhan Mantri Matsya Sampada Yojana completed six years.',
 pts=['Aim: fill gaps across the fisheries value chain. Department of Fisheries. Components: Central Sector (genetic improvement, disease surveillance) and Centrally Sponsored (production, infrastructure, post-harvest). Sub-scheme PM Matsya Kisan Samridhi Sah-Yojana (formalisation, insurance, finance, traceability).','Fish production 141.64 lakh tonnes (2019-20) to 197.75 lakh tonnes (2024-25); India is the second-largest producer (about 8% of global); exports Rs 46,663 crore to Rs 73,890 crore (2025-26); 2,195 FFPOs supported.'],
 kw='Blue Revolution; FFPO; Value chain'),
dict(id='2.10.19',sub='Economy',nb=['gs3'],ch=['gs3-ch03'],tag='P',
 t='Rising sulphur prices',
 ctx='Global sulphur prices rose on disruption in Russia and West Asia and EV battery demand, raising phosphatic fertiliser costs.',
 pts=['Sulphur makes sulphuric acid; about 2.6-2.8 tonnes of sulphuric acid per tonne of phosphoric acid. Sulphur is a by-product of oil refining and gas processing. Nickel processing for EV batteries lifted sulphuric acid demand from 3.5 million tonnes (2021) to 16 million tonnes (2025).'],
 kw='Fertiliser input costs'),
dict(id='2.10.20',sub='Economy',nb=['gs3'],ch=['gs3-ch06','gs3-ch03'],tag='P',
 t='PM Kisan Maandhan Yojana completes seven years',
 ctx='About 25 lakh farmers had enrolled by February 2026.',
 pts=['Launched 2019; voluntary, contributory pension for small and marginal farmers; Central Sector; Ministry of Agriculture. Eligibility: farmers aged 18-40 with up to two hectares. Pension Rs 3,000 per month after 60. Contribution Rs 55-200 per month by age, matched by the Centre. LIC manages the fund.','Ineligible: covered under NPS, EPFO, ESIC; institutional landholders, income-tax payers, professionals, certain officials, holders of constitutional posts.'],
 kw='Old-age security; Contributory pension'),
]
